def comps(points, conn=4):
 pts=set(points); outs=[]
 deltas=[(dr,dc) for dr in [-1,0,1] for dc in [-1,0,1] if (dr or dc) and (conn==8 or abs(dr)+abs(dc)==1)]
 while pts:
