def norm(s):
 mr=min(r for r,c in s);mc=min(c for r,c in s)
 return frozenset((r-mr,c-mc) for r,c in s)

def d4(s):
 # normalize transformation in any shape's bbox
 h=max(r for r,c in s)+1;w=max(c for r,c in s)+1
 fs=[lambda r,c:(r,c),lambda r,c:(c,h-1-r),lambda r,c:(h-1-r,w-1-c),lambda r,c:(w-1-c,r),lambda r,c:(h-1-r,c),lambda r,c:(r,w-1-c),lambda r,c:(c,r),lambda r,c:(w-1-c,h-1-r)]
 return [norm({f(r,c) for r,c in s}) for f in fs]
